async function showPastDateWarning(app) {
  return new Promise((resolve) => {
    const warningModal = new import_obsidian6.Modal(app);
    warningModal.titleEl.setText("Past due date warning");
    const content = warningModal.contentEl;
    const messageEl = content.createEl("p");
    messageEl.setText("The due date you entered is in the past.");
    messageEl.style.marginBottom = "1em";
    const questionEl = content.createEl("p");
    questionEl.setText(
      "Would you like to proceed with creating the task or edit the due date?"
    );
    questionEl.style.marginBottom = "2em";
    const buttonContainer = content.createEl("div");
    buttonContainer.style.display = "flex";
    buttonContainer.style.justifyContent = "space-between";
    buttonContainer.style.gap = "10px";
    const editButton = buttonContainer.createEl("button", {
      text: "Edit due date"
    });
    editButton.style.flexGrow = "1";
    editButton.addEventListener("click", () => {
      warningModal.close();
      resolve(false);
    });
    const proceedButton = buttonContainer.createEl("button", {
      text: "Proceed anyway",
      cls: "mod-warning"
    });
    proceedButton.style.flexGrow = "1";
    proceedButton.addEventListener("click", () => {
      warningModal.close();
      resolve(true);
    });
    warningModal.open();
  });
}

// src/constants.ts
var TODOIST_CONSTANTS = {
  // Link related constants
  WEBSITE_LINK_TEXT: "\u{1F517} View in Todoist website",
  APP_LINK_TEXT: "\u{1F4F1} View in Todoist app",
  COMBINED_LINK_TEXT: (websiteUrl, appUrl) => `[\u{1F517} View in Todoist website](${websiteUrl}) [\u{1F4F1} View in Todoist app](${appUrl})`,
  // Link patterns for different formats
  WEBSITE_LINK_PATTERN: /\[🔗 View in Todoist website\]\(https:\/\/(?:app\.)?todoist\.com(?:\/app)?(?:\/task|\/t)\/([\w-]+)\)/,
  APP_LINK_PATTERN: /\[📱 View in Todoist app\]\(todoist:\/\/task\?id=([\w-]+)\)/,
  COMBINED_LINK_PATTERN: /\[🔗 View in Todoist website\]\(https:\/\/(?:app\.)?todoist\.com(?:\/app)?(?:\/task|\/t)\/([\w-]+)\) \[📱 View in Todoist app\]\(todoist:\/\/task\?id=([\w-]+)\)/,
  // General link pattern that matches any format
  LINK_PATTERN: /(?:\[🔗 View in Todoist website\]|\[📱 View in Todoist app\]|\[🔗 View in Todoist website\].*\[📱 View in Todoist app\]).*?(?:https:\/\/(?:app\.)?todoist\.com(?:\/app)?(?:\/task|\/t)\/|todoist:\/\/task\?id=)([\w-]+)/,
  // Metadata patterns
  METADATA: {
    ORIGINAL_TASK: "Original task in Obsidian",
    REFERENCE: "Reference in Obsidian",
    CREATED_AT: "Created"
  },
  // Full metadata patterns for matching
  METADATA_PATTERNS: {
    ORIGINAL_TASK: /Original task in Obsidian(?:: | \()(.+?)(?:\)| \(Created: .*\))/,
    REFERENCE: /Reference in Obsidian(?:: | \()(.+?)(?:\)| \(Created: .*\))/
  },
  // Metadata format strings
  FORMAT_STRINGS: {
    ORIGINAL_TASK: (uri, timestamp, useMdLinkFormat = false) => useMdLinkFormat ? `[Original task in Obsidian](${uri}) (Created: ${timestamp})` : `Original task in Obsidian: ${uri} (Created: ${timestamp})`,
    REFERENCE: (uri, timestamp, useMdLinkFormat = false) => useMdLinkFormat ? `[Reference in Obsidian](${uri}) (Created: ${timestamp})` : `Reference in Obsidian: ${uri} (Created: ${timestamp})`,
    TODOIST_LINK: (indentation, linkText, url2, timestamp) => `
${indentation}- [${linkText}](${url2}) (Created: ${timestamp})`,
    COMBINED_TODOIST_LINK: (indentation, websiteUrl, appUrl, timestamp) => `
${indentation}- [${TODOIST_CONSTANTS.WEBSITE_LINK_TEXT}](${websiteUrl}) [${TODOIST_CONSTANTS.APP_LINK_TEXT}](${appUrl}) (Created: ${timestamp})`
  }
};

// src/NotificationHelper.ts
var import_obsidian7 = require("obsidian");
var NotificationHelper = class {
  constructor(settings) {
    this.settings = settings;
  }
  /**
   * Shows a success notification if user preferences allow it
   * @param message The success message to display
   */
  showSuccess(message) {
    if (this.shouldShowNotification("success")) {
      new import_obsidian7.Notice(message);
    }
  }
  /**
   * Shows an error notification if user preferences allow it
   * @param message The error message to display
   */
  showError(message) {
    if (this.shouldShowNotification("error")) {
      new import_obsidian7.Notice(message);
    }
  }
  /**
   * Shows an info notification if user preferences allow it
   * @param message The info message to display
   */
  showInfo(message) {
    if (this.shouldShowNotification("info")) {
      new import_obsidian7.Notice(message);
    }
  }
  /**
   * Determines if a notification should be shown based on user preferences
   * @param type The type of notification: "success", "error", or "info"
   * @returns true if the notification should be shown
   */
  shouldShowNotification(type) {
    const preference = this.getEffectiveNotificationPreference();
    switch (preference) {
      case "none":
        return false;
      case "errors":
        return type === "error";
      case "all":
        return true;
      default:
        return true;
    }
  }
  /**
   * Gets the effective notification preference based on platform
   * @returns The notification preference to use
   */
  getEffectiveNotificationPreference() {
    if (import_obsidian7.Platform.isMobile && this.settings.mobileNotificationPreference !== null) {
      return this.settings.mobileNotificationPreference;
    }
    return this.settings.notificationPreference;
  }
};

